import { verifyArtifactConstraints } from '@hyperfocus/artifact-review/constraints';
import { dirname, resolve } from 'node:path';

// Inventory is optional for archive inspection, required to check newly generated bytes.
const [manifestPath, inventoryPath, ...extra] = process.argv.slice(2);
if (!manifestPath || extra.length) throw new Error('Usage: bun run art:check <constraints.json> [asset-inventory.json]');
let assets: { id: string; bytes: Uint8Array }[] | undefined;
if (inventoryPath) {
  const raw: unknown = await Bun.file(inventoryPath).json();
  if (!raw || typeof raw !== 'object' || !('assets' in raw) || !Array.isArray(raw.assets)) throw new Error('Inventory needs assets: [{ id, path }]');
  assets = await Promise.all(raw.assets.map(async (value: unknown) => {
    if (!value || typeof value !== 'object' || !('id' in value) || typeof value.id !== 'string' || !value.id.trim()
      || !('path' in value) || typeof value.path !== 'string' || !value.path.trim()) throw new Error('Invalid asset inventory item');
    return { id: value.id, bytes: new Uint8Array(await Bun.file(resolve(dirname(inventoryPath), value.path)).arrayBuffer()) };
  }));
}
console.log(JSON.stringify(await verifyArtifactConstraints({ manifestPath, assets }), null, 2));
